        testLandscape();testMultiFileArchive();testOriginalQQModule();testSubsonicSession();testAsyncAndPersistence();testNativeNetwork();testOriginalLizhi();testPlaybackPipeline();testBrowserLogin();testLiveSources();testAdditionalLiveSources();
        result.putString("stream","MYGO_TESTS_OK: landscape, ES modules, async result, errors, storage, native fetch, cookies, permissions, original Li Zhi search/stream/like/lyrics, source to Android audio playback, browser login and cookie isolation, complete ZIP install, relative and dynamic modules, rejected update rollback, original QQ module, Subsonic authenticated search/stream/session\n"+liveResult);
