    private byte[] zip(Map<String,String> files)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(java.util.zip.ZipOutputStream out=new java.util.zip.ZipOutputStream(bytes)){for(Map.Entry<String,String> file:files.entrySet()){out.putNextEntry(new java.util.zip.ZipEntry(file.getKey()));out.write(file.getValue().getBytes("UTF-8"));out.closeEntry();}}return bytes.toByteArray();}
    private String install(PluginManager manager,byte[] bytes,boolean expected)throws Exception{CountDownLatch done=new CountDownLatch(1);boolean[] ok={false};String[] result={""};manager.installZipStream(new ByteArrayInputStream(bytes),(success,raw)->{ok[0]=success;result[0]=raw;done.countDown();});check(done.await(45,TimeUnit.SECONDS),"ZIP install callback missing");check(ok[0]==expected,result[0]);return result[0];}
    private String managerCall(PluginManager manager,String id,String fn,JSONObject args)throws Exception{CountDownLatch done=new CountDownLatch(1);boolean[] ok={false};String[] result={""};manager.export(id,fn,args,(success,raw)->{ok[0]=success;result[0]=raw;done.countDown();});check(done.await(55,TimeUnit.SECONDS),"source callback missing: "+fn);check(ok[0],result[0]);return result[0];}
    private void testMultiFileArchive()throws Exception{
        PluginManager manager=new PluginManager(getTargetContext());try{Map<String,String> files=new LinkedHashMap<>();files.put("pkg/plugin.json","{\"id\":\"module-fixture\",\"main\":\"src/index.js\"}");files.put("pkg/src/index.js","import {value} from '../lib/value.js';export async function run(){const m=await import('../lib/dynamic.js');const r=await fetch(new URL('../data/config.json',import.meta.url));return {value:value(),dynamic:m.dynamic,config:await r.json()};}");files.put("pkg/lib/value.js","import {bias} from './shared.js';export function value(){return 40+bias;}");files.put("pkg/lib/shared.js","import {value} from './value.js';export const bias=2;export const read=()=>value();");files.put("pkg/lib/dynamic.js","export const dynamic=7;");files.put("pkg/data/config.json","{\"title\":\"local-resource\"}");install(manager,zip(files),true);JSONObject result=new JSONObject(managerCall(manager,"module-fixture","run",new JSONObject()));check(result.getInt("value")==42&&result.getInt("dynamic")==7&&result.getJSONObject("config").getString("title").equals("local-resource"),"relative modules or asset fetch failed");files.put("pkg/src/index.js","throw new Error('invalid update');export function run(){}");install(manager,zip(files),false);check(new JSONObject(managerCall(manager,"module-fixture","run",new JSONObject())).getInt("value")==42,"failed update replaced working plugin");File outside=new File(getTargetContext().getCacheDir(),"must-not-exist");outside.delete();Map<String,String> bad=new LinkedHashMap<>();bad.put("../must-not-exist","bad");File target=new File(getTargetContext().getCacheDir(),"zip-traversal-test");boolean rejected=false;try{PluginArchive.extract(new ByteArrayInputStream(zip(bad)),target);}catch(IOException expected){rejected=true;}check(rejected&&!outside.exists(),"archive escaped staging directory");PluginArchive.delete(target);}finally{runOnMainSync(manager::close);}}
