    private void testSubsonicSession()throws Exception{
        ServerSocket server=new ServerSocket(0);boolean[] authenticated={false};String song="{\"id\":\"one\",\"title\":\"Fixture song\",\"artist\":\"Fixture artist\",\"album\":\"Fixture album\",\"suffix\":\"mp3\",\"contentType\":\"audio/mpeg\",\"duration\":5}";
        Thread worker=new Thread(()->{while(!server.isClosed())try(Socket connection=server.accept()){connection.setSoTimeout(5000);BufferedReader reader=new BufferedReader(new InputStreamReader(connection.getInputStream(),"UTF-8"));String request=reader.readLine(),line;int length=0;while((line=reader.readLine())!=null&&!line.isEmpty())if(line.toLowerCase(Locale.ROOT).startsWith("content-length:"))length=Integer.parseInt(line.substring(15).trim());char[] body=new char[length];int got=0,n;while(got<length&&(n=reader.read(body,got,length-got))!=-1)got+=n;Map<String,String> form=new HashMap<>();for(String pair:new String(body,0,got).split("&")){String[] item=pair.split("=",2);form.put(URLDecoder.decode(item[0],"UTF-8"),item.length>1?URLDecoder.decode(item[1],"UTF-8"):"");}String salt=form.get("s");String token="";if(salt!=null){for(byte value:java.security.MessageDigest.getInstance("MD5").digest(("fixture-password"+salt).getBytes("UTF-8")))token+=String.format(Locale.US,"%02x",value&255);}boolean valid="fixture-user".equals(form.get("u"))&&token.equals(form.get("t"));authenticated[0]|=valid;String payload=valid?"\"status\":\"ok\",\"version\":\"1.16.1\"":"\"status\":\"failed\",\"error\":{\"code\":40,\"message\":\"Unauthorized\"}";if(valid&&request.contains("/search3.view"))payload+=",\"searchResult3\":{\"song\":["+song+"]}";if(valid&&request.contains("/getSong.view"))payload+=",\"song\":"+song;byte[] answer=("{\"subsonic-response\":{"+payload+"}}").getBytes("UTF-8");connection.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+answer.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));connection.getOutputStream().write(answer);}catch(Exception ignored){}});worker.setDaemon(true);worker.start();
        String id="subsonic-fixture";getTargetContext().getSharedPreferences("plugin_settings_"+id,0).edit().putString("serverUrl","http://127.0.0.1:"+server.getLocalPort()).putString("username","fixture-user").putString("password","fixture-password").commit();getTargetContext().getSharedPreferences("library",0).edit().putBoolean("plugin_network_"+id,true).commit();fixture(id,read("subsonic.js"),new JSONArray().put("127.0.0.1")).dispose();Activity activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();PluginRuntime rt=new PluginRuntime(activity,new File(getTargetContext().getCacheDir(),id));runtimes.add(rt);try{check(new JSONObject(call(rt,"signIn",new JSONObject())).getString("id").equals("fixture-user"),"Subsonic login failed");check(authenticated[0],"Subsonic token authentication was not used");check(new JSONObject(call(rt,"search",new JSONObject().put("kind","tracks").put("query","Fixture"))).getJSONArray("tracks").length()==1,"Subsonic search failed");String url=new JSONObject(call(rt,"stream",new JSONObject().put("id","one"))).getString("url");check(url.contains("/rest/stream.view")&&!url.contains("fixture-password"),"Subsonic stream resolution failed");rt.dispose();PluginRuntime fresh=new PluginRuntime(activity,new File(getTargetContext().getCacheDir(),id));runtimes.add(fresh);check(new JSONObject(call(fresh,"account",new JSONObject())).getString("id").equals("fixture-user"),"Subsonic account not persisted");}finally{rt.dispose();runOnMainSync(activity::finish);server.close();}
    }
